import{_ as t,o as e,c as o,a5 as a}from"./chunks/framework.BPFk9-tb.js";const m=JSON.parse('{"title":"写作课作业-058","description":"","frontmatter":{"date":"2020-09-15T20:03:08","title":"写作课作业-058","categories":["写作","作业"],"tags":["写作","作业"]},"headers":[],"relativePath":"posts/homework/058.md","filePath":"posts/homework/058.md"}'),s={name:"posts/homework/058.md"};function l(i,p,r,_,c,n){return e(),o("div",null,[...p[0]||(p[0]=[a("<blockquote><p>9.15写作作业：你最重要的五个优先事务是什么？哪些可以授权他人做，哪个一定要自己做？</p></blockquote><p>我最重要的的5个优先事务是：</p><ul><li><p>工作</p></li><li><p>阅读</p></li><li><p>写作课作业</p></li><li><p>辅导儿子作业</p></li><li><p>锻炼</p></li></ul><p>说工作是一个比较笼统的说法了，但自己是坐班，这份工作也是自己的主要收入来源，这个事情必须自己做，并且要做好。具体的工作事项看情况会做授权。</p><p>阅读也只能自己做，输入是输出的基础，同时通过改变阅读习惯——划词性，来练习自己的感知能力。</p><p>写作课作业只能自己做，为的就是改掉自己只是看看而已，只是听听而已的问题，让自己在行动中真有所收获。</p><p>辅导儿子作业，基本上是和妻子两个人配合来辅导，中午和晚上是我辅导，下午放学时我妻子辅导。为什么自己呢？一是自己相对有时间，可以多一些陪伴。另一方面也想他能养成一个学习的习惯。其实做写作课作业也会影响小孩，因为有次孩子说，我睡觉的时候，爸爸就要去做作业了。</p><p>锻炼，这个事情是想授权也授权不的了，保持一周两三次的运动，或游泳，或跑步，或走步。</p>",8)])])}const u=t(s,[["render",l]]);export{m as __pageData,u as default};
